package com.bank.portal.domain; import jakarta.persistence.*; import java.time.LocalDate; import lombok.*;
@Entity @Table(name="credit_score_events") @Getter @Setter @NoArgsConstructor public class CreditScoreEvent extends BaseEntity { @ManyToOne(optional=false) @JoinColumn(name="customer_id") private Customer customer; @ManyToOne @JoinColumn(name="card_id") private CreditCard card; @Enumerated(EnumType.STRING) @Column(nullable=false) private CreditScoreEventType eventType; @Column(nullable=false) private Integer points; @Column(nullable=false) private LocalDate eventDate; private String referenceKey; private String description; }
